/* Token Radar — one dark palette, consistent spacing, readable type.
   Palette: deep green-black canvas, emerald accent, warm amber for the
   top row only. No external assets, no network. */
:root {
  --canvas: #0a0f0d;
  --surface: #101613;
  --panel: #141c18;
  --panel-2: #18221d;
  --ink: #e9f0eb;
  --ink-2: #c3d2c8;
  --muted: #8fa398;
  --faint: #64766c;
  --border: #233028;
  --border-strong: #31473a;
  --accent: #34d399;
  --accent-dim: #1d7a58;
  --accent-ink: #06281c;
  --amber: #fbbf24;
  --negative: #f87171;
  --positive: #34d399;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 16px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--step-2) var(--step-4);
  background: var(--panel); border: 1px solid var(--border-strong); z-index: 20;
}
.skip:focus { left: var(--step-4); top: var(--step-4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--step-5) var(--step-6) var(--step-7); }
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--step-5);
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); flex: none; box-shadow: 0 0 12px rgba(52, 211, 153, 0.55); }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.04em; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-3); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.top-meta .model-tag { color: var(--accent); border: 1px solid var(--border-strong); border-radius: 999px; padding: 2px 10px; }
.lede { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr); gap: var(--step-6); padding: var(--step-6) 0 var(--step-5); }
.lede p { color: var(--muted); max-width: 62ch; margin-top: var(--step-2); }
.lede p b { color: var(--ink-2); font-weight: 600; }
.facts { display: grid; gap: var(--step-2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--step-5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--step-3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 500; color: var(--ink); }
.fact span { color: var(--muted); font-size: 13px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--step-3); padding: var(--step-4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--step-1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--step-3); border: 1px solid var(--border-strong); border-radius: var(--radius-control);
  background: var(--panel); min-width: 170px; color: var(--ink);
}
.field input { min-width: 260px; }
.field input::placeholder { color: var(--faint); }
.field select option { background: var(--panel); }
.tabs { display: flex; gap: var(--step-1); padding: 3px; border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--panel); }
.tabs button { min-height: 30px; padding: 0 var(--step-3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
.table-wrap table caption { text-align: left; padding: var(--step-3) var(--step-4) var(--step-2); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: var(--step-3) var(--step-3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
th { color: var(--muted); font-size: 12px; font-weight: 500; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--step-1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
th button .arrow { color: var(--accent); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel-2); }
tbody tr[data-selected="true"] { background: rgba(52, 211, 153, 0.09); }
tbody tr.top-row td:first-child { color: var(--amber); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--positive); }
.neg { color: var(--negative); }
.bar { width: 120px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--step-2); }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
.status.live::before { background: var(--amber); }

.model { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.model h2 { display: flex; align-items: baseline; gap: var(--step-3); flex-wrap: wrap; }
.model h2 .model-tag { font-family: var(--font-num); font-size: 12px; color: var(--accent); border: 1px solid var(--border-strong); border-radius: 999px; padding: 2px 10px; font-weight: 500; }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--ink-2); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--step-3) var(--step-4); overflow-wrap: anywhere; }
.formula b { color: var(--accent); font-weight: 600; }
.model dl { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--step-3); margin: 0; }
.model dl div { border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--step-3); background: var(--surface); }
.model dt { font-family: var(--font-num); font-size: 12px; color: var(--accent); margin-bottom: var(--step-1); }
.model dd { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.5; }
.empty { padding: var(--step-7) var(--step-5); text-align: center; display: grid; gap: var(--step-3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--step-4); border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--panel); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 10;
  background: var(--panel); border-left: 1px solid var(--border-strong); padding: var(--step-5);
  overflow-y: auto; color: var(--ink);
}
.detail[hidden] { display: none; }
.detail { margin: 0 0 0 auto; max-height: 100%; }
.detail::backdrop { background: rgba(4, 8, 6, 0.6); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--step-4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 var(--step-2); white-space: nowrap; border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--surface); color: var(--ink); }
.detail h2 { margin-top: var(--step-1); }
.detail .sub { margin-top: var(--step-1); }
.detail-section { margin-top: var(--step-5); padding-top: var(--step-4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--step-2); }
.equation { display: grid; gap: var(--step-2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--step-3); padding: var(--step-1) 0; border-bottom: 1px dashed var(--border); }
.equation div:last-child { border-bottom: 0; }
.equation span { color: var(--muted); }
.equation .total { font-size: 15px; }
.equation .total b { color: var(--accent); }
.steps { margin: 0; padding-left: var(--step-5); display: grid; gap: var(--step-3); }
.steps li { padding-left: var(--step-1); }
.steps li::marker { color: var(--accent); font-family: var(--font-num); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

@media (max-width: 900px) {
  .shell { padding: var(--step-4); }
  .lede { grid-template-columns: 1fr; gap: var(--step-4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--step-4); }
  .field input { min-width: 0; width: 100%; }
  .count { margin-left: 0; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
